mkdir -p ~/gastrodex-live/pwa && cd ~/gastrodex-live
cat << 'EOF' > firebase.json
{"hosting": {"public": "pwa", "rewrites": [{"source": "**", "destination": "/index.html"}]}}
EOF
python3 -c "import base64, gzip; open('pwa/index.html', 'wb').write(gzip.decompress(base64.b64decode('')))"
firebase deploy --project gastrodex-823d7 --only hosting
